            java.awt.Graphics2D g = sourceImage.createGraphics();
            g.setColor(java.awt.Color.BLUE);
            g.fillRect(0, 0, sourceImage.getWidth(), sourceImage.getHeight());
            g.dispose();

            java.util.Map<java.awt.RenderingHints.Key, Object> hints = new java.util.HashMap<>();
            hints.put(java.awt.RenderingHints.KEY_RENDERING, java.awt.RenderingHints.VALUE_RENDER_QUALITY);
            hints.put(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

            net.coobird.thumbnailator.resizers.BilinearResizer resizer = new net.coobird.thumbnailator.resizers.BilinearResizer(hints);

            int newWidth = Math.max(1, sourceImage.getWidth() / 2);
            int newHeight = Math.max(1, sourceImage.getHeight() / 2);
            java.awt.image.BufferedImage dest = new java.awt.image.BufferedImage(newWidth, newHeight, java.awt.image.BufferedImage.TYPE_INT_ARGB);

            resizer.resize(sourceImage, dest);

            int centerRgb = dest.getRGB(newWidth / 2, newHeight / 2);
            assert (centerRgb & 0xFFFFFF) == 0x0000FF : "Center pixel should be blue, got " + Integer.toHexString(centerRgb);

            System.out.println("__CHECK__ BilinearResizer " + Integer.toHexString(centerRgb));
            // TODO API_TEST_END
            System.out.println("__DONE__");
